document.querySelector('#today').textContent=new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});
setInterval(()=>document.querySelector('#clock').textContent=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',second:'2-digit'}),1000);
async function api(url,opt={}){
  let token=window.suvidhaAuthToken||null;
  if(!token){try{token=sessionStorage.getItem('suvidha_auth_token')}catch{}}
  const headers=new Headers(opt.headers||{});
  if(token) headers.set('Authorization','Bearer '+token);
  const r=await fetch(url,{...opt,headers,credentials:'same-origin',cache:opt.cache||'no-store'});
  const raw=await r.text();let d={};try{d=raw?JSON.parse(raw):{}}catch{}
  if(r.status===401){
    window.suvidhaAuthToken=null;
    try{sessionStorage.removeItem('suvidha_auth_token')}catch{}
    document.body.removeAttribute('data-authenticated');
    const screen=document.querySelector('#loginScreen');
    if(screen)screen.style.setProperty('display','flex','important');
    throw new Error(token?'Session expired. Please login again.':'Login required');
  }
  if(!r.ok){
    const detail=d.message||d.detail||(raw&&raw.length<=700?raw:'')||('HTTP '+r.status);
    throw new Error(detail+' ['+url+']');
  }
  return d
}
