async function loadDashboard(){setPage('dashboard');title.textContent='Dashboard';try{const [d,chart]=await Promise.all([api('/api/dashboard'),api('/api/dashboard/chart?days=7')]);const max=Math.max(1,...chart.map(x=>Number(x.Sales)));app.innerHTML=`<div class="content dashboard-premium"><div class="dashboard-welcome"><div><span>SUVIDHAPOS PREMIUM</span><b>Business Command Center</b><small>Sales, stock and business health at a glance</small></div><div class="dashboard-welcome-chip">● SQL <strong>CONNECTED</strong></div></div><div class="cards">
${card('Today\'s Sales','₹'+money(d.TodaySales),"Today's completed billing",'▣')} ${card('Today\'s Bills',d.TodayBills,'Completed invoices','▤')} ${card('Gross Profit','₹'+money(d.GrossProfit),'After item cost & discount','↗')} ${card('Stock Value','₹'+money(d.StockValue),'Current inventory value','◈')} ${card('Expiry ≤ 30d',d.Expiring30,d.ExpiredBatches+' already expired','◷')}</div>
<div class="grid"><div class="panel"><div class="panelhead"><h3>SALES OVERVIEW</h3><span class="tag">LAST 7 DAYS</span></div><div class="chart">${chart.map(x=>`<div class="bar" style="height:${Math.max(5,Number(x.Sales)/max*88)}%"><em>₹${money(x.Sales)}</em><label>${new Date(x.Date).toLocaleDateString('en-IN',{weekday:'short'})}</label></div>`).join('')||'<div class="empty">No sales data yet</div>'}</div></div>
<div class="panel"><h3>INVENTORY HEALTH</h3><div class="donut"></div><div class="legend"><span>Products ${d.TotalProducts}</span><span>Low stock ${d.LowStock}</span><span>Expiry ${d.Expiring30}</span><span>Expired ${d.ExpiredBatches}</span></div></div>
<div class="panel"><h3>ALERT CENTER</h3><div class="mini"><span class="muted">Low Stock</span><b class="${d.LowStock?'dangerText':'successText'}">${d.LowStock} items</b></div><br><div class="mini"><span class="muted">Expiry</span><b class="${d.Expiring30?'dangerText':'successText'}">${d.Expiring30} batches</b></div><br><button class="btn block" onclick="loadExpiry()">Open Expiry Center</button></div></div>
<div class="twocol"><div class="panel"><div class="panelhead"><h3>QUICK ACTIONS</h3></div><div class="toolbar"><button class="btn" onclick="loadBilling()">＋ New Bill</button><button class="btn" onclick="loadPurchase()">＋ Purchase</button><button class="btn secondary" onclick="openUomProduct()">＋ Item</button><button class="btn secondary" onclick="loadReports()">Reports</button><button class="btn secondary" onclick="loadNormalItemImportMaster()">⇩ Item Import</button></div></div><div class="panel"><div class="panelhead"><h3>BUSINESS SNAPSHOT</h3></div><div class="metricrow"><div class="mini">Customers<b>${d.Customers}</b></div><div class="mini">Suppliers<b>${d.Suppliers}</b></div><div class="mini">Tax today<b>₹${money(d.TodayTax)}</b></div><div class="mini">Stock units<b>${money(d.TotalStock)}</b></div></div></div></div></div>`}catch(e){app.innerHTML=errorBox(e)}}
function card(l,v,s,i){return `<div class="card"><span class="icon">${i}</span><div class="label">${l}</div><div class="value">${v}</div><div class="sub">${s}</div></div>`}
function errorBox(e){return `<div class="content"><div class="alert">${esc(e.message)}</div><p class="muted" style="margin-top:8px">If this is a database screen, check SQL Server. If this is AI Import, use Test AI Connection.</p></div>`}

async function loadProducts(){setPage('products');title.textContent='Items & Inventory';try{const rows=await api('/api/products?size=500');state.products=rows;app.innerHTML=`<div class="content"><div class="toolbar"><input id="pq" class="input" placeholder="Search item, barcode, SKU or category..." oninput="filterTable('productRows',this.value)"><button class="btn" onclick="openProduct()">＋ Add Item</button><button class="btn secondary" onclick="openProductBulkEdit()">✎ Bulk Edit</button><button class="btn secondary" onclick="loadStock()">Stock View</button></div><div class="panel"><div class="panelhead"><h3>PRODUCT CATALOG</h3><span class="tag">${rows.length} ITEMS</span></div><div class="tablewrap"><table class="table"><thead><tr><th>ITEM</th><th>RACK / LOCATION</th><th>BARCODE</th><th>CATEGORY</th><th>MRP</th><th>PURCHASE</th><th>SALE</th><th>STOCK</th><th>GST</th><th>ACTION</th></tr></thead><tbody id="productRows">${rows.map(productRow).join('')}</tbody></table></div></div></div>`}catch(e){app.innerHTML=errorBox(e)}}
function productRow(x){return `<tr><td><b>${esc(x.Name)}</b><br><small class="muted">${esc(x.Sku||'')}</small></td><td><span class="tag">${esc(x.LocationCode||x.RackName||'-')}</span></td><td>${esc(x.Barcode||'-')}</td><td>${esc(x.Category||'-')}</td><td>₹${money(x.Mrp)}</td><td>₹${money(x.PurchasePrice)}</td><td>₹${money(x.SalePrice)}</td><td><span class="status ${x.Stock<=0?'out':x.Stock<=x.MinStock?'low':'ok'}">${money(x.Stock)}</span></td><td>${x.GstRate}%</td><td><div class="actions"><button class="btn small" onclick="editProduct(${x.Id})">Edit</button><button class="btn small secondary" onclick="viewBatches(${x.Id},'${esc(x.Name)}')">Batches</button></div></td></tr>`}
function filterTable(id,q){const term=q.toLowerCase();document.querySelectorAll('#'+id+' tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(term)?'':'none')}
async function openProduct(id=null){let x={Name:'',Barcode:'',Sku:'',Category:'General',Unit:'PCS',Hsn:'',GstRate:0,TaxMode:'EXCLUSIVE',Mrp:0,PurchasePrice:0,SalePrice:0,MinStock:5,MaxStock:0,LocationCode:'',RackName:'',ShelfName:'',TrackBatch:true,TrackExpiry:true};if(id)x=await api('/api/products/'+id);const m=modal(`${id?'Edit':'Add'} Product`,`<div class="formgrid"><label class="full">Item Name<input id="pn" class="input" value="${esc(x.Name)}"></label><label>Barcode<input id="pb" class="input" value="${esc(x.Barcode)}"></label><label>SKU<input id="ps" class="input" value="${esc(x.Sku)}"></label><label>Category<input id="pc" class="input" value="${esc(x.Category)}"></label><label>Unit<input id="pu" class="input" value="${esc(x.Unit)}"></label><label>HSN/SAC<input id="ph" class="input" value="${esc(x.Hsn)}"></label><label>GST %<input id="pg" class="input" type="number" step="0.01" value="${x.GstRate}"></label><label>Tax Mode<select id="ptaxmode" class="select"><option value="EXCLUSIVE" ${String(x.TaxMode||'EXCLUSIVE').toUpperCase()==='EXCLUSIVE'?'selected':''}>Exclusive</option><option value="INCLUSIVE" ${String(x.TaxMode||'').toUpperCase()==='INCLUSIVE'?'selected':''}>Inclusive</option></select></label><label>MRP<input id="pm" class="input" type="number" step="0.01" value="${x.Mrp}"></label><label>Purchase Price<input id="pp" class="input" type="number" step="0.01" value="${x.PurchasePrice}"></label><label>Sale Price<input id="psp" class="input" type="number" step="0.01" value="${x.SalePrice}"></label><label>Minimum Stock<input id="pmin" class="input" type="number" step="0.001" value="${x.MinStock}"></label><label>Maximum Stock<input id="pmax" class="input" type="number" step="0.001" value="${x.MaxStock}"></label><label>Location Code<input id="ploc" class="input" placeholder="A-1 / R3-S2" value="${esc(x.LocationCode||'')}"></label><label>Rack Name<input id="prack" class="input" placeholder="Rack A" value="${esc(x.RackName||'')}"></label><label>Shelf Name<input id="pshelf" class="input" placeholder="Shelf 1" value="${esc(x.ShelfName||'')}"></label><label class="full"><input id="ptrack" type="checkbox" ${x.TrackBatch!==false?'checked':''}> Track Batch &nbsp;&nbsp; <input id="ptexp" type="checkbox" ${x.TrackExpiry!==false?'checked':''}> Track Expiry</label></div>`,`<button class="btn" onclick="saveProduct(${id||0})">Save Item</button>`);return m}
async function validateProductIdentity(name,barcode,excludeId=0){
  const n=(name||'').trim(),b=(barcode||'').trim();
  if(!n)return {duplicate:true,message:'Item name is required'};
  try{
    const r=await api('/api/products/identity-check?name='+encodeURIComponent(n)+'&barcode='+encodeURIComponent(b)+'&excludeId='+excludeId);
    if(r.duplicate){const c=r.conflict||{};return {duplicate:true,message:'Duplicate '+(c.ConflictType==='NAME'?'Item Name':'Barcode')+': '+(c.Name||n)+' already exists.'}}
    return {duplicate:false}
  }catch(e){return {duplicate:true,message:e.message}}
}
async function saveProduct(id){try{const check=await validateProductIdentity(pn.value,pb.value,id);if(check.duplicate)return alert(check.message);const body={Name:pn.value.trim(),Barcode:pb.value.trim()||null,Sku:ps.value.trim()||null,CategoryId:null,Category:pc.value||'General',Unit:pu.value||'PCS',Hsn:ph.value||null,GstRate:+pg.value,TaxMode:ptaxmode.value||'EXCLUSIVE',Mrp:+pm.value,PurchasePrice:+pp.value,SalePrice:+psp.value,MinStock:+pmin.value,MaxStock:+pmax.value,LocationCode:ploc.value||null,RackName:prack.value||null,ShelfName:pshelf.value||null,TrackBatch:ptrack.checked,TrackExpiry:ptexp.checked};await api(id?'/api/products/'+id:'/api/products',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});closeModal();toast('Product saved');loadProducts()}catch(e){alert(e.message)}}
async function openProductBulkEdit(){try{const rows=await api('/api/products?size=1000');state.bulkRows=rows.map(x=>({...x}));modal('Bulk Edit Items',`<div class="alert">Duplicate Item Name / Barcode save nahi hoga.</div><div class="tablewrap" style="max-height:60vh"><table class="table"><thead><tr><th>NAME</th><th>BARCODE</th><th>SKU</th><th>CATEGORY</th><th>MRP</th><th>PURCHASE</th><th>SALE</th></tr></thead><tbody>${state.bulkRows.map((x,i)=>`<tr><td><input class="input" value="${esc(x.Name)}" onchange="state.bulkRows[${i}].Name=this.value"></td><td><input class="input" value="${esc(x.Barcode||'')}" onchange="state.bulkRows[${i}].Barcode=this.value"></td><td><input class="input" value="${esc(x.Sku||'')}" onchange="state.bulkRows[${i}].Sku=this.value"></td><td><input class="input" value="${esc(x.Category||'')}" onchange="state.bulkRows[${i}].Category=this.value"></td><td><input class="input" type="number" value="${x.Mrp||0}" onchange="state.bulkRows[${i}].Mrp=+this.value"></td><td><input class="input" type="number" value="${x.PurchasePrice||0}" onchange="state.bulkRows[${i}].PurchasePrice=+this.value"></td><td><input class="input" type="number" value="${x.SalePrice||0}" onchange="state.bulkRows[${i}].SalePrice=+this.value"></td></tr>`).join('')}</tbody></table></div>`,`<button class="btn" onclick="saveGenericBulkEdit()">Validate & Save All</button>`);const mb=document.querySelector('#modal .modalbox');if(mb){mb.style.width='94vw';mb.style.maxWidth='1400px'}}catch(e){alert(e.message)}}
async function saveGenericBulkEdit(){try{const r=await api('/api/products/bulk-edit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({Rows:(state.bulkRows||[]).map(x=>({Id:x.Id,Name:(x.Name||'').trim(),Barcode:(x.Barcode||'').trim()||null,Sku:(x.Sku||'').trim()||null,Category:x.Category||'General',Unit:x.Unit||'PCS',Hsn:x.Hsn||null,GstRate:+x.GstRate||0,Mrp:+x.Mrp||0,PurchasePrice:+x.PurchasePrice||0,SalePrice:+x.SalePrice||0,MinStock:+x.MinStock||0,MaxStock:+x.MaxStock||0,LocationCode:x.LocationCode||null,RackName:x.RackName||null,ShelfName:x.ShelfName||null}))})});closeModal();toast('Bulk edit saved: '+r.updated+' items');loadProducts()}catch(e){alert(e.message)}}
function editProduct(id){openProduct(id)}
async function viewBatches(id,name){const rows=await api('/api/batches/'+id);modal(name+' — Batches',`<div class="tablewrap"><table class="table"><thead><tr><th>BATCH</th><th>QTY</th><th>COST</th><th>SALE</th><th>EXPIRY</th><th>STATUS</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.BatchNo)}</td><td>${money(x.Quantity)}</td><td>₹${money(x.CostPrice)}</td><td>₹${money(x.SellingPrice)}</td><td>${fmt(x.ExpiryDate)}</td><td><span class="status ${x.DaysLeft<0?'out':x.DaysLeft<=30?'low':'ok'}">${x.DaysLeft<0?'EXPIRED':x.DaysLeft+' DAYS'}</span></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No batches</td></tr>'}</tbody></table></div>`,'<button class="btn secondary" onclick="closeModal()">Close</button>')}
async function loadStock(){setPage('products');title.textContent='Stock Management';const rows=await api('/api/stock');app.innerHTML=`<div class="content"><div class="toolbar"><input id="sq" class="input" placeholder="Search stock..." oninput="filterTable('stockRows',this.value)"><button class="btn" onclick="openAdjustment()">＋ Stock Adjustment</button><button class="btn secondary" onclick="loadOpeningStockMaster()">Opening Stock</button><button class="btn secondary" onclick="loadExpiry()">Expiry</button></div><div class="panel"><div class="tablewrap"><table class="table"><thead><tr><th>ITEM</th><th>STOCK</th><th>SALEABLE</th><th>VALUE</th><th>MIN</th><th>STATUS</th><th></th></tr></thead><tbody id="stockRows">${rows.map(x=>`<tr><td><b>${esc(x.Name)}</b><br><small class="muted">${esc(x.Barcode||'')}</small></td><td>${money(x.Stock)}</td><td>${money(x.SaleableStock)}</td><td>₹${money(x.StockValue)}</td><td>${money(x.MinStock)}</td><td><span class="status ${x.Status==='OUT'?'out':x.Status==='LOW'?'low':'ok'}">${x.Status}</span></td><td><button class="btn small" onclick="openAdjustment(${x.Id},'${esc(x.Name)}')">Adjust</button></td></tr>`).join('')}</tbody></table></div></div></div>`}

async function loadBilling(){setPage('billing');title.textContent='New Billing';state.products=await api('/api/products?size=500');state.cart=[];app.innerHTML=`<div class="content"><div class="pos"><div><div class="toolbar"><input id="billSearch" class="input search" autofocus placeholder="Scan barcode / search item..." oninput="billSearchFn(this.value)"><button class="btn secondary" onclick="billSearchFn('')">All</button></div><div class="panel"><div class="panelhead"><h3>ITEMS</h3><span class="tag">FEFO STOCK</span></div><div id="suggestions"><div class="empty">Start typing or scan a barcode</div></div></div></div><div class="panel cart"><div class="panelhead"><h3>CURRENT BILL</h3><button class="btn small secondary" onclick="state.cart=[];renderCart()">Clear</button></div><div id="cart"></div><div class="totalbox"><div class="totalrow"><span>Subtotal</span><b id="subtotal">₹0.00</b></div><div class="totalrow"><span>Discount</span><input id="billDiscount" class="input" style="max-width:120px" type="number" value="0" oninput="renderCart()"></div><div class="totalrow"><span>Tax</span><b id="tax">₹0.00</b></div><div class="totalrow grand"><span>TOTAL</span><b id="total">₹0.00</b></div><select id="payment" class="select" style="width:100%;margin-top:7px"><option>Cash</option><option>UPI</option><option>Card</option><option>Credit</option><option>Mixed</option></select><button class="btn green block" style="margin-top:8px;padding:14px" onclick="payBill()">PAY & COMPLETE BILL</button></div></div></div></div>`;document.querySelector('#billSearch').focus()}
function billSearchFn(q){const s=document.querySelector('#suggestions');q=q.trim().toLowerCase();const a=state.products.filter(x=>!q||(x.Name+' '+(x.Barcode||'')+' '+(x.Sku||'')+' '+(x.LocationCode||'')).toLowerCase().includes(q)).slice(0,12);s.innerHTML=a.map(x=>`<div class="suggest"><div><b>${esc(x.Name)}</b><br><small class="muted">${esc(x.Barcode||x.Sku||'')} • Rack <b>${esc(x.LocationCode||x.RackName||'-')}</b> • Stock ${money(x.Stock)} • ₹${money(x.SalePrice)}</small></div><button class="btn small" ${x.Stock<=0?'disabled':''} onclick="addCart(${x.Id})">ADD</button></div>`).join('')||'<div class="empty">No matching items</div>'}
function addCart(id){const p=state.products.find(x=>x.Id===id);if(!p||p.Stock<=0)return toast('Item is out of stock');let c=state.cart.find(x=>x.Id===id);if(c){if(c.Qty+1>p.Stock)return toast('Stock limit reached');c.Qty++}else state.cart.push({Id:p.Id,Name:p.Name,Qty:1,Rate:Number(p.SalePrice),Gst:Number(p.GstRate),Stock:Number(p.Stock)});renderCart();document.querySelector('#billSearch').value='';billSearchFn('')}
function renderCart(){const box=document.querySelector('#cart');if(!box)return;box.innerHTML=state.cart.map((x,i)=>`<div class="cartline"><div><b>${esc(x.Name)}</b><br><small class="muted">₹${money(x.Rate)} × ${x.Qty} • GST ${x.Gst}%</small></div><input class="input qty" type="number" min="1" max="${x.Stock}" value="${x.Qty}" onchange="changeQty(${i},this.value)"><b>₹${money(x.Rate*x.Qty)}</b><button class="btn small danger" onclick="state.cart.splice(${i},1);renderCart()">×</button></div>`).join('')||'<div class="empty">No items in bill</div>';const sub=state.cart.reduce((a,x)=>a+x.Qty*x.Rate,0),disc=Number(document.querySelector('#billDiscount')?.value||0),tax=state.cart.reduce((a,x)=>a+x.Qty*x.Rate*x.Gst/100,0),tot=Math.max(0,sub-disc+tax);document.querySelector('#subtotal').textContent='₹'+money(sub);document.querySelector('#tax').textContent='₹'+money(tax);document.querySelector('#total').textContent='₹'+money(tot)}
function changeQty(i,v){v=Math.max(1,Number(v)||1);state.cart[i].Qty=Math.min(v,state.cart[i].Stock);renderCart()}
async function payBill(){if(!state.cart.length)return toast('Add item first');try{const discount=Number(document.querySelector('#billDiscount').value||0);const data=await api('/api/sales',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({CustomerId:null,CustomerName:'Walk-in Customer',PaymentMode:document.querySelector('#payment').value,PaidAmount:0,Discount:discount,Notes:null,Lines:state.cart.map(x=>({ProductId:x.Id,Qty:x.Qty,SalePrice:x.Rate,TaxRate:x.Gst,Discount:0}))})});toast('Bill completed successfully');printLastBill(data.id);setTimeout(loadBilling,700)}catch(e){alert(e.message)}}
async function printLastBill(id){try{const rows=await api('/api/sales?from=1900-01-01&to=2999-12-31');const x=rows.find(a=>a.Id===id)||rows[0];if(!x)return;const w=window.open('','_blank');w.document.write(`<html><body><div class="receipt"><h2>SUVIDHA POS</h2><p>Tax Invoice</p><p>${esc(x.InvoiceNo)} • ${fmt(x.BillDate)}</p><hr><p style="text-align:right;font-weight:bold">TOTAL ₹${money(x.GrandTotal)}</p></div><script>window.print()<\/script></body></html>`);w.document.close()}catch{}}

async function loadPurchase(){setPage('purchase');title.textContent='Purchases';state.products=await api('/api/products?size=500');state.suppliers=await api('/api/suppliers');let lines=[];app.innerHTML=`<div class="content"><div class="toolbar"><button class="btn" onclick="openPurchase()">＋ New Purchase</button><input id="purSearch" class="input" placeholder="Filter purchase history..." oninput="filterTable('purchaseRows',this.value)"></div><div class="panel"><div class="panelhead"><h3>PURCHASE HISTORY</h3><span class="tag">LOCAL SQL</span></div><div class="tablewrap"><table class="table"><thead><tr><th>INVOICE</th><th>SUPPLIER</th><th>DATE</th><th>SUBTOTAL</th><th>TAX</th><th>TOTAL</th><th>PAID</th><th>BALANCE</th></tr></thead><tbody id="purchaseRows">${(await api('/api/purchases')).map(x=>`<tr><td><b>${esc(x.InvoiceNo)}</b></td><td>${esc(x.SupplierName)}</td><td>${fmt(x.PurchaseDate)}</td><td>₹${money(x.SubTotal)}</td><td>₹${money(x.Tax)}</td><td>₹${money(x.GrandTotal)}</td><td>₹${money(x.PaidAmount)}</td><td class="${x.Balance>0?'dangerText':'successText'}">₹${money(x.Balance)}</td></tr>`).join('')}</tbody></table></div></div></div>`}
function openPurchase(){state.purLines=[];const m=modal('New Purchase',`<div class="formgrid"><label>Invoice No<input id="pi" class="input"></label><label>Supplier<select id="psup" class="select"><option value="">Walk-in Supplier</option>${state.suppliers.map(x=>`<option value="${x.Id}">${esc(x.Name)}</option>`).join('')}</select></label></div><div class="toolbar" style="margin-top:14px"><select id="pprod" class="select" style="flex:1"><option value="">Select product</option>${state.products.map(x=>`<option value="${x.Id}">${esc(x.Name)} • ${esc(x.Barcode||'')}</option>`).join('')}</select><button class="btn" onclick="addPurchaseLine()">Add</button></div><div id="purLines"></div><div class="formgrid" style="margin-top:12px"><label>Discount<input id="pdisc" class="input" type="number" value="0"></label><label>Paid Amount<input id="ppaid" class="input" type="number" value="0"></label><label>Payment Mode<select id="ppm" class="select"><option>Credit</option><option>Cash</option><option>UPI</option><option>Card</option></select></label><label>Notes<input id="pnotes" class="input"></label></div>`, '<button class="btn" onclick="savePurchase()">Save Purchase</button>');window.purModal=m}
function addPurchaseLine(){const id=Number(document.querySelector('#pprod').value);if(!id)return;const p=state.products.find(x=>x.Id===id);state.purLines.push({ProductId:id,Name:p.Name,Qty:1,FreeQuantity:0,Cost:p.PurchasePrice,SalePrice:p.SalePrice,Mrp:p.Mrp,GstRate:p.GstRate,BatchNo:'',ExpiryDate:''});renderPurchaseLines()}
function renderPurchaseLines(){document.querySelector('#purLines').innerHTML=state.purLines.map((x,i)=>`<div class="panel" style="margin:7px 0"><div class="formgrid"><label>Item<input class="input" value="${esc(x.Name)}" disabled></label><label>Batch<input class="input" value="${esc(x.BatchNo)}" onchange="state.purLines[${i}].BatchNo=this.value"></label><label>Qty<input class="input" type="number" value="${x.Qty}" onchange="state.purLines[${i}].Qty=+this.value"></label><label>Free Qty<input class="input" type="number" value="${x.FreeQuantity}" onchange="state.purLines[${i}].FreeQuantity=+this.value"></label><label>Cost<input class="input" type="number" value="${x.Cost}" onchange="state.purLines[${i}].Cost=+this.value"></label><label>Sale Price<input class="input" type="number" value="${x.SalePrice}" onchange="state.purLines[${i}].SalePrice=+this.value"></label><label>MRP<input class="input" type="number" value="${x.Mrp}" onchange="state.purLines[${i}].Mrp=+this.value"></label><label>Expiry<input class="input" type="date" value="${x.ExpiryDate}" onchange="state.purLines[${i}].ExpiryDate=this.value"></label></div><button class="btn small danger" style="margin-top:8px" onclick="state.purLines.splice(${i},1);renderPurchaseLines()">Remove</button></div>`).join('')}
async function savePurchase(){if(!state.purLines?.length)return toast('Add purchase items');if(state.purLines.some(x=>!x.ExpiryDate))return toast('Expiry date is required for every batch');try{const sid=Number(psup.value)||null;const s=state.suppliers.find(x=>x.Id===sid);await api('/api/purchases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({InvoiceNo:pi.value||null,SupplierId:sid,SupplierName:s?.Name||'Walk-in Supplier',PaymentMode:ppm.value,PaidAmount:+ppaid.value,Discount:+pdisc.value,Notes:pnotes.value||null,Lines:state.purLines.map(x=>({...x,ManufactureDate:null}))})});closeModal();toast('Purchase saved and stock updated');loadPurchase()}catch(e){alert(e.message)}}

async function loadSales(){setPage('sales');title.textContent='Sales History';const rows=await api('/api/sales');app.innerHTML=`<div class="content"><div class="toolbar"><input id="salesQ" class="input" placeholder="Search invoice, customer or payment mode..." oninput="filterTable('salesRows',this.value)"><button class="btn secondary" onclick="loadBillMaster()">Bill Management</button><button class="btn secondary" onclick="loadReports()">Sales Report</button></div><div class="panel"><div class="tablewrap"><table class="table"><thead><tr><th>INVOICE</th><th>DATE</th><th>CUSTOMER</th><th>PAYMENT</th><th>SUBTOTAL</th><th>DISCOUNT</th><th>TAX</th><th>TOTAL</th><th>PROFIT</th><th>ACTION</th></tr></thead><tbody id="salesRows">${rows.map(x=>`<tr><td><b>${esc(x.InvoiceNo)}</b></td><td>${fmt(x.BillDate)}</td><td>${esc(x.CustomerName)}</td><td><span class="tag">${esc(x.PaymentMode)}</span></td><td>₹${money(x.SubTotal)}</td><td>₹${money(x.Discount)}</td><td>₹${money(x.Tax)}</td><td><b>₹${money(x.GrandTotal)}</b></td><td class="successText">₹${money(x.Profit)}</td><td><button class="btn small" onclick="viewSale(${x.Id})">View</button> ${x.Status==='Completed'?`<button class="btn small danger" onclick="voidSale(${x.Id})">Cancel</button>`:''}</td></tr>`).join('')}</tbody></table></div></div></div>`}

async function viewSale(id){const [h,l]=await Promise.all([api('/api/sales/'+id),api('/api/sales/'+id+'/lines')]);modal('Invoice '+esc(h.InvoiceNo),`<div class="invoice-preview"><div class="metricrow"><div class="mini">Customer<b>${esc(h.CustomerName)}</b></div><div class="mini">Payment<b>${esc(h.PaymentMode)}</b></div><div class="mini">Date<b>${fmt(h.BillDate)}</b></div><div class="mini">Total<b>₹${money(h.GrandTotal)}</b></div></div><div class="tablewrap"><table class="table"><thead><tr><th>ITEM</th><th>BATCH</th><th>QTY</th><th>RATE</th><th>TAX</th><th>AMOUNT</th></tr></thead><tbody>${l.map(x=>`<tr><td>${esc(x.Name)}</td><td>${esc(x.BatchNo)}</td><td>${money(x.Quantity)}</td><td>₹${money(x.SalePrice)}</td><td>${x.TaxRate}%</td><td>₹${money(Number(x.Quantity)*Number(x.SalePrice))}</td></tr>`).join('')}</tbody></table></div></div>`,`<button class="btn" onclick="printInvoice(${id})">🖨 Print</button>`)}
async function printInvoice(id){const h=await api('/api/sales/'+id),l=await api('/api/sales/'+id+'/lines');const w=window.open('','_blank','width=420,height=700');w.document.write(`<html><head><title>${esc(h.InvoiceNo)}</title><style>body{font-family:Arial;padding:18px}table{width:100%;border-collapse:collapse}td,th{padding:6px;border-bottom:1px solid #ddd;text-align:left}.r{text-align:right}</style></head><body><h2>SUVIDHA POS</h2><div>Invoice: ${esc(h.InvoiceNo)}<br>${fmt(h.BillDate)}<br>Customer: ${esc(h.CustomerName)}</div><hr><table><tr><th>Item</th><th>Qty</th><th>Rate</th><th class="r">Amount</th></tr>${l.map(x=>`<tr><td>${esc(x.Name)}</td><td>${money(x.Quantity)}</td><td>₹${money(x.SalePrice)}</td><td class="r">₹${money(Number(x.Quantity)*Number(x.SalePrice))}</td></tr>`).join('')}</table><hr><h3 class="r">TOTAL ₹${money(h.GrandTotal)}</h3><script>window.print()<\/script></body></html>`);w.document.close()}
async function voidSale(id){if(!confirm('Cancel this bill and restore its stock?'))return;try{await api('/api/sales/'+id+'/void',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({Reason:'Cancelled from Sales History'})});toast('Bill cancelled and stock restored');loadSales();}catch(e){alert(e.message)}}

async function loadCustomers(){setPage('customers');title.textContent='Customers';const rows=await api('/api/customers');app.innerHTML=partyPage('CUSTOMERS',rows,'customerRows','openCustomer',`Name`,`Phone`,`Balance`)}
async function loadSuppliers(){setPage('suppliers');title.textContent='Suppliers';const rows=await api('/api/suppliers');app.innerHTML=partyPage('SUPPLIERS',rows,'supplierRows','openSupplier',`Name`,`Phone`,`Balance`)}
function partyPage(head,rows,id,fn,a,b,c){const kind=head==='CUSTOMERS'?'Customer':'Supplier';return `<div class="content"><div class="toolbar"><input class="input" placeholder="Search ${head.toLowerCase()}..." oninput="filterTable('${id}',this.value)"><button class="btn" onclick="${fn}()">＋ Add ${kind}</button></div><div class="panel"><table class="table"><thead><tr><th>${a.toUpperCase()}</th><th>${b.toUpperCase()}</th><th>ADDRESS</th><th>GSTIN</th><th>${c.toUpperCase()}</th><th>ACTION</th></tr></thead><tbody id="${id}">${rows.map(x=>`<tr><td><b>${esc(x.Name)}</b></td><td>${esc(x.Phone||'-')}</td><td>${esc(x.Address||'-')}</td><td>${esc(x.GstIn||'-')}</td><td class="${x.Balance>0?'dangerText':'successText'}">₹${money(x.Balance)}</td><td><button class="btn small" onclick="partyPayment(${x.Id},'${kind}')">Receive/Pay</button><button class="btn small secondary" onclick="partyLedger(${x.Id},'${kind}')">Ledger</button></td></tr>`).join('')}</tbody></table></div></div>`}
function partyPayment(id,kind){modal(kind==='Customer'?'Receive Payment':'Pay Supplier',`<div class="formgrid"><label>Amount<input id="payAmt" class="input" type="number" step="0.01"></label><label>Payment Mode<select id="payMode" class="select"><option>Cash</option><option>UPI</option><option>Card</option><option>Bank</option></select></label><label>Reference<input id="payRef" class="input"></label><label class="full">Notes<input id="payNotes" class="input"></label></div>`,`<button class="btn" onclick="savePartyPayment(${id},'${kind}')">Save Payment</button>`)}
async function savePartyPayment(id,kind){const url=(kind==='Customer'?'/api/customers/':'/api/suppliers/')+id+'/payments';try{await api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({Amount:+payAmt.value,PaymentMode:payMode.value,ReferenceNo:payRef.value,Notes:payNotes.value})});closeModal();toast('Payment saved');kind==='Customer'?loadCustomers():loadSuppliers()}catch(e){alert(e.message)}}
async function partyLedger(id,kind){const rows=await api((kind==='Customer'?'/api/customers/':'/api/suppliers/')+id+'/ledger');modal(kind+' Ledger',`<div class="tablewrap"><table class="table"><thead><tr><th>DATE</th><th>TYPE</th><th>REFERENCE</th><th>DEBIT</th><th>CREDIT</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${fmt(x.TxnDate)}</td><td>${esc(x.Type)}</td><td>${esc(x.RefNo)}</td><td>₹${money(x.Debit)}</td><td class="successText">₹${money(x.Credit)}</td></tr>`).join('')||'<tr><td colspan="5">No transactions</td></tr>'}</tbody></table></div>`)}

function openCustomer(){openParty('Customer','/api/customers')};function openSupplier(){openParty('Supplier','/api/suppliers')}
function openParty(kind,url){modal('Add '+kind,`<div class="formgrid"><label>Name<input id="partyName" class="input"></label><label>Phone<input id="partyPhone" class="input"></label><label>GSTIN<input id="partyGst" class="input"></label><label>Opening Balance<input id="partyBal" class="input" type="number" value="0"></label><label class="full">Address<textarea id="partyAddress" class="textarea"></textarea></label></div>`,`<button class="btn" onclick="saveParty('${kind}','${url}')">Save</button>`) }
async function saveParty(kind,url){try{await api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({Name:partyName.value,Phone:partyPhone.value,Address:partyAddress.value,GstIn:partyGst.value,OpeningBalance:+partyBal.value})});closeModal();toast(kind+' saved');kind==='Customer'?loadCustomers():loadSuppliers()}catch(e){alert(e.message)}}

async function loadExpiry(){setPage('expiry');title.textContent='Expiry Center';const rows=await api('/api/expiry?days=365');app.innerHTML=`<div class="content"><div class="toolbar"><span class="tag">FEFO ENABLED</span><button class="btn secondary" onclick="loadExpiryDays(30)">30 Days</button><button class="btn secondary" onclick="loadExpiryDays(90)">90 Days</button><button class="btn secondary" onclick="loadExpiryDays(365)">1 Year</button></div><div class="panel"><div class="tablewrap"><table class="table"><thead><tr><th>ITEM</th><th>BATCH</th><th>QTY</th><th>COST</th><th>MRP</th><th>EXPIRY</th><th>DAYS LEFT</th><th>STATUS</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.Name)}</b><br><small class="muted">${esc(x.Barcode||'')}</small></td><td>${esc(x.BatchNo)}</td><td>${money(x.Quantity)}</td><td>₹${money(x.CostPrice)}</td><td>₹${money(x.Mrp)}</td><td>${fmt(x.ExpiryDate)}</td><td>${x.DaysLeft}</td><td><span class="status ${x.DaysLeft<0?'out':x.DaysLeft<=30?'low':'ok'}">${x.DaysLeft<0?'EXPIRED':x.DaysLeft<=30?'EXPIRING':'UPCOMING'}</span></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No expiry records</td></tr>'}</tbody></table></div></div></div>`}
function loadExpiryDays(d){api('/api/expiry?days='+d).then(rows=>{const t=document.querySelector('.table tbody');t.innerHTML=rows.map(x=>`<tr><td><b>${esc(x.Name)}</b></td><td>${esc(x.BatchNo)}</td><td>${money(x.Quantity)}</td><td>₹${money(x.CostPrice)}</td><td>₹${money(x.Mrp)}</td><td>${fmt(x.ExpiryDate)}</td><td>${x.DaysLeft}</td><td><span class="status ${x.DaysLeft<0?'out':x.DaysLeft<=30?'low':'ok'}">${x.DaysLeft<0?'EXPIRED':x.DaysLeft<=30?'EXPIRING':'UPCOMING'}</span></td></tr>`).join('')})}

async function loadReturns(){setPage('returns');title.textContent='Returns & Adjustments';state.products=await api('/api/products?size=500');app.innerHTML=`<div class="content"><div class="twocol"><div class="panel"><h3>SALES RETURN</h3><p class="muted">Return stock to inventory against a sold batch.</p><button class="btn" onclick="openReturn(false)">＋ Sales Return</button></div><div class="panel"><h3>PURCHASE RETURN</h3><p class="muted">Return purchased stock to supplier and reduce inventory.</p><button class="btn" onclick="openReturn(true)">＋ Purchase Return</button></div></div><div class="alert" style="margin-top:14px">Returns are posted through the same Stock Ledger used by billing and purchases.</div></div>`}
function openReturn(purchase){state.returnLines=[];modal(purchase?'Purchase Return':'Sales Return',`<div class="formgrid"><label>Party Name<input id="rparty" class="input"></label><label>Reason<input id="rreason" class="input"></label></div><div class="toolbar" style="margin-top:14px"><select id="rprod" class="select" style="flex:1"><option value="">Select product</option>${state.products.map(x=>`<option value="${x.Id}">${esc(x.Name)}</option>`).join('')}</select><button class="btn" onclick="addReturnLine()">Add</button></div><div id="returnLines"></div>`,`<button class="btn" onclick="saveReturn(${purchase})">Post Return</button>`);window.returnPurchase=purchase}
async function addReturnLine(){const id=Number(rprod.value);if(!id)return;const bs=await api('/api/batches/'+id);const b=bs.find(x=>x.Quantity>0);if(!b)return toast('No stock batch available');state.returnLines.push({ProductId:id,BatchId:b.Id,Name:state.products.find(x=>x.Id===id).Name,Qty:1,Rate:Number(b.SellingPrice||b.CostPrice)});renderReturnLines()}
function renderReturnLines(){document.querySelector('#returnLines').innerHTML=state.returnLines.map((x,i)=>`<div class="toolbar"><span style="flex:1"><b>${esc(x.Name)}</b> • Batch ${x.BatchId}</span><input class="input" style="max-width:90px" type="number" value="${x.Qty}" onchange="state.returnLines[${i}].Qty=+this.value"><span>₹${money(x.Rate)}</span><button class="btn small danger" onclick="state.returnLines.splice(${i},1);renderReturnLines()">×</button></div>`).join('')}
async function saveReturn(purchase){if(!state.returnLines.length)return toast('Add return items');try{await api(purchase?'/api/purchase-return':'/api/sales-return',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({PartyName:rparty.value,Reason:rreason.value,Lines:state.returnLines.map(x=>({ProductId:x.ProductId,BatchId:x.BatchId,Qty:x.Qty,Rate:x.Rate}))})});closeModal();toast('Return posted successfully')}catch(e){alert(e.message)}}

async function loadExpenses(){setPage('expenses');title.textContent='Expenses';const rows=await api('/api/expenses');app.innerHTML=`<div class="content"><div class="toolbar"><button class="btn" onclick="openExpense()">＋ Add Expense</button></div><div class="panel"><table class="table"><thead><tr><th>DATE</th><th>CATEGORY</th><th>AMOUNT</th><th>PAYMENT</th><th>NOTES</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${fmt(x.ExpenseDate)}</td><td>${esc(x.Category)}</td><td class="dangerText">₹${money(x.Amount)}</td><td>${esc(x.PaymentMode)}</td><td>${esc(x.Notes||'')}</td></tr>`).join('')}</tbody></table></div></div>`}
function openExpense(){modal('Add Expense',`<div class="formgrid"><label>Date<input id="edate" class="input" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Category<input id="ecat" class="input" value="General"></label><label>Amount<input id="eamt" class="input" type="number" value="0"></label><label>Payment<select id="epay" class="select"><option>Cash</option><option>UPI</option><option>Card</option><option>Bank</option></select></label><label class="full">Notes<input id="enotes" class="input"></label></div>`,`<button class="btn" onclick="saveExpense()">Save Expense</button>`)}
async function saveExpense(){try{await api('/api/expenses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({Date:edate.value,Category:ecat.value,Amount:+eamt.value,PaymentMode:epay.value,Notes:enotes.value})});closeModal();toast('Expense saved');loadExpenses()}catch(e){alert(e.message)}}

async function loadReports(){setPage('reports');title.textContent='Reports & Analytics';const from=new Date();from.setDate(1);const f=from.toISOString().slice(0,10),t=new Date().toISOString().slice(0,10);const [sum,top,pay,stock]=await Promise.all([api(`/api/reports/sales-summary?from=${f}&to=${t}`),api(`/api/reports/top-items?from=${f}&to=${t}`),api(`/api/reports/payment?from=${f}&to=${t}`),api('/api/stock')]);app.innerHTML=`<div class="content"><div class="metricrow"><div class="mini">Days Sales<b>₹${money(sum.reduce((a,x)=>a+Number(x.Sales),0))}</b></div><div class="mini">Profit<b>₹${money(sum.reduce((a,x)=>a+Number(x.Profit),0))}</b></div><div class="mini">Bills<b>${sum.reduce((a,x)=>a+Number(x.Bills),0)}</b></div><div class="mini">Stock Value<b>₹${money(stock.reduce((a,x)=>a+Number(x.StockValue),0))}</b></div></div><div class="reportgrid" style="margin-top:14px"><div class="panel"><h3>DAILY SALES</h3><table class="table"><thead><tr><th>DATE</th><th>BILLS</th><th>SALES</th><th>PROFIT</th></tr></thead><tbody>${sum.map(x=>`<tr><td>${fmt(x.Date)}</td><td>${x.Bills}</td><td>₹${money(x.Sales)}</td><td class="successText">₹${money(x.Profit)}</td></tr>`).join('')}</tbody></table></div><div class="panel"><h3>TOP SELLING ITEMS</h3><table class="table"><thead><tr><th>ITEM</th><th>QTY</th><th>SALES</th><th>PROFIT</th></tr></thead><tbody>${top.slice(0,15).map(x=>`<tr><td>${esc(x.Name)}</td><td>${money(x.Qty)}</td><td>₹${money(x.Sales)}</td><td>₹${money(x.Profit)}</td></tr>`).join('')}</tbody></table></div><div class="panel"><h3>PAYMENT MODES</h3><table class="table"><thead><tr><th>MODE</th><th>BILLS</th><th>AMOUNT</th></tr></thead><tbody>${pay.map(x=>`<tr><td>${esc(x.PaymentMode)}</td><td>${x.Bills}</td><td>₹${money(x.Amount)}</td></tr>`).join('')}</tbody></table></div><div class="panel"><h3>STOCK ALERTS</h3><table class="table"><thead><tr><th>ITEM</th><th>STOCK</th><th>VALUE</th><th>STATUS</th></tr></thead><tbody>${stock.filter(x=>x.Status!=='OK').slice(0,20).map(x=>`<tr><td>${esc(x.Name)}</td><td>${money(x.Stock)}</td><td>₹${money(x.StockValue)}</td><td><span class="status ${x.Status==='OUT'?'out':'low'}">${x.Status}</span></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No stock alerts</td></tr>'}</tbody></table></div></div></div>`}

async function openAdjustment(id,name){if(!id){state.products=await api('/api/products?size=500')}modal('Stock Adjustment',`<div class="formgrid"><label class="full">Product<select id="adjp" class="select">${state.products.map(x=>`<option value="${x.Id}" ${x.Id===id?'selected':''}>${esc(x.Name)}</option>`).join('')}</select></label><label>Quantity<input id="adjq" class="input" type="number" value="0" step="0.001"><small class="muted">Positive adds stock, negative removes stock</small></label><label>Batch<input id="adjb" class="input" value="ADJ"></label><label>Cost Price<input id="adjc" class="input" type="number" value="0"></label><label>Sale Price<input id="adjs" class="input" type="number" value="0"></label><label>MRP<input id="adjm" class="input" type="number" value="0"></label><label>Expiry<input id="adje" class="input" type="date" value="${new Date(Date.now()+31536000000).toISOString().slice(0,10)}"></label><label class="full">Notes<input id="adjn" class="input"></label></div>`,`<button class="btn" onclick="saveAdjustment()">Post Adjustment</button>`)}
async function saveAdjustment(){try{await api('/api/stock-adjustment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ProductId:+adjp.value,BatchNo:adjb.value,Quantity:+adjq.value,CostPrice:+adjc.value,SalePrice:+adjs.value,Mrp:+adjm.value,ExpiryDate:adje.value,Notes:adjn.value})});closeModal();toast('Stock adjustment posted');loadStock()}catch(e){alert(e.message)}}

async function loadAIImport(){
 setPage('aiimport');title.textContent='AI Import Center';document.querySelector('header p').textContent='PDF, Excel, image and message extraction with review before posting';
 let cfg={configured:false,model:'gpt-5.6-luna'},cfgError='';try{cfg=await api('/api/ai/config')}catch(err){cfgError=err.message||'Configuration status unavailable'}
 app.innerHTML=`<div class="content">
  <div class="panel" style="margin-bottom:14px"><div class="panelhead"><div><h3>AI CONNECTION</h3><p class="muted">OpenAI connection is independent of SQL Server.</p></div><span id="aiConnBadge" class="tag">${cfg.configured?'KEY CONFIGURED':(cfgError?'STATUS CHECK FAILED':'KEY NOT CONFIGURED')}</span></div>
   <div class="toolbar"><span class="tag">Model: ${esc(cfg.model||'gpt-5.6-luna')}</span><span class="muted">${cfg.configured?'Key source: '+esc(cfg.source||'server'):(cfgError?'Could not read key status: '+esc(cfgError):'Open Settings → AI Configuration to save an API key.')}</span><button class="btn secondary" onclick="testAIConnection()">Test AI Connection</button><button class="btn secondary" onclick="loadSettings()">AI Settings</button></div><div id="aiConnStatus"></div>
  </div>
  <div class="grid"><div class="panel"><div class="panelhead"><h3>AI ITEM / PURCHASE IMPORT</h3><span class="tag">PDF • EXCEL • IMAGE • MESSAGE</span></div>
   <p class="muted">Upload a scanned PDF, Excel file, photo/handwritten note, or paste a WhatsApp/SMS-style message. PDF files are uploaded to OpenAI as a temporary file for extraction and deleted after processing. Nothing is posted automatically.</p>
   <label>Import Mode<select id="aimode" class="select"><option value="items">Item Master</option><option value="purchase">Purchase Entry</option></select></label>
   <label style="display:block;margin-top:10px">File<input id="aifile" class="input" type="file" accept=".pdf,.xlsx,.xls,.csv,.txt,image/*" onchange="showAiFileInfo()"></label>
   <div id="aiFileInfo" class="muted" style="margin-top:6px"></div>
   <label style="display:block;margin-top:10px">Message / Notes<textarea id="aimsg" class="textarea" placeholder="Example: Paracetamol 500mg, batch AB12, expiry 2027-04, qty 50, MRP 25, rack A-1"></textarea></label>
   <button id="aiExtractBtn" class="btn" style="margin-top:12px" onclick="runAIImport()">✦ Extract with AI</button>
  </div><div class="panel"><h3>HOW IT WORKS</h3>
   <div class="mini"><b>1. Upload</b><span class="muted">Scanned PDF, Excel, photo, handwritten note or text message.</span></div>
   <div class="mini" style="margin-top:8px"><b>2. AI extracts</b><span class="muted">Name, barcode, batch, expiry, MRP, purchase/sale price, quantity, GST and rack/location.</span></div>
   <div class="mini" style="margin-top:8px"><b>3. Review</b><span class="muted">Edit uncertain rows and verify medicines/expiry before posting.</span></div>
   <div class="mini" style="margin-top:8px"><b>4. Post</b><span class="muted">Only verified rows are committed to SQL Server.</span></div>
  </div></div><div id="aiPreview" style="margin-top:14px"></div></div>`
}
function showAiFileInfo(){const f=document.querySelector('#aifile')?.files?.[0],e=document.querySelector('#aiFileInfo');if(!e)return;e.textContent=f?f.name+' • '+(f.size/1024/1024).toFixed(2)+' MB'+(f.type?' • '+f.type:''):''}
async function testAIConnection(){const box=document.querySelector('#aiConnStatus'),btn=document.querySelector('#aiExtractBtn');if(box)box.innerHTML='<div class="alert" style="margin-top:10px">Testing OpenAI API…</div>';try{const r=await api('/api/ai/test',{method:'POST'});if(box)box.innerHTML='<div class="alert" style="margin-top:10px;border-color:#2f8f61;color:#73d9a2">✓ OpenAI connection OK · '+esc(r.model||'')+'</div>';const badge=document.querySelector('#aiConnBadge');if(badge)badge.textContent='CONNECTED';if(btn){btn.disabled=false;btn.title=''} }catch(e){if(box)box.innerHTML='<div class="alert" style="margin-top:10px">'+esc(e.message)+'</div>'}}
async function runAIImport(){
 const file=aifile.files[0],message=(aimsg.value||'').trim();if(!file&&!message)return alert('Choose a PDF / Excel / image or enter Message / Notes first.');
 const fd=new FormData();fd.append('mode',aimode.value);fd.append('message',message);if(file)fd.append('file',file);
 const box=document.querySelector('#aiPreview'),btn=document.querySelector('#aiExtractBtn');if(btn){btn.disabled=true;btn.textContent='✦ Extracting…'};box.innerHTML='<div class="panel"><b>AI is reading the source…</b><p class="muted">PDF extraction can take a little longer. Please wait.</p></div>';
 try{
  const r=await api('/api/ai/import',{method:'POST',body:fd});state.aiRows=r.rows||[];
  box.innerHTML=`<div class="panel"><div class="panelhead"><h3>REVIEW DRAFT</h3><span class="tag">${state.aiRows.length} ROWS · ${esc(r.model||'AI')}</span></div><div class="alert">${esc(r.warning||'Review before posting.')}</div><div class="tablewrap"><table class="table"><thead><tr><th>ITEM</th><th>BARCODE</th><th>RACK</th><th>BATCH</th><th>QTY</th><th>MRP</th><th>PURCHASE</th><th>SALE</th><th>EXPIRY</th><th>CONFIDENCE</th></tr></thead><tbody>${state.aiRows.map((x,i)=>`<tr><td><input class="input" value="${esc(x.name||'')}" onchange="state.aiRows[${i}].name=this.value"></td><td>${esc(x.barcode||'-')}</td><td>${esc(x.locationCode||x.rackName||'-')}</td><td>${esc(x.batchNo||'-')}</td><td>${x.quantity||0}</td><td>₹${money(x.mrp||0)}</td><td>₹${money(x.purchasePrice||0)}</td><td>₹${money(x.salePrice||0)}</td><td>${esc(x.expiryDate||'-')}</td><td>${Math.round((x.confidence||0)*100)}%</td></tr>`).join('')||'<tr><td colspan="10" class="empty">No rows extracted</td></tr>'}</tbody></table></div><div class="toolbar" style="margin-top:12px"><button class="btn" onclick="commitAIImport()">✓ Post Verified Rows</button><button class="btn secondary" onclick="state.aiRows=[];document.querySelector('#aiPreview').innerHTML=''">Discard</button></div></div>`
 }catch(e){
  box.innerHTML=`<div class="panel"><div class="panelhead"><h3>AI IMPORT ERROR</h3><span class="tag">NOT SQL SERVER</span></div><div class="alert">${esc(e.message)}</div><p class="muted">Use “Test AI Connection” above. Common causes: invalid/expired API key, no API credits/quota, firewall/proxy blocking api.openai.com, or an unsupported/corrupt file.</p></div>`
 }finally{if(btn){btn.disabled=false;btn.textContent='✦ Extract with AI'}}
}
async function commitAIImport(){if(!state.aiRows?.length)return;try{if(aimode.value==='items'){const r=await api('/api/ai/import/items/commit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({Rows:state.aiRows})});toast(`Imported ${r.added} new · skipped ${r.skipped||0} duplicate/invalid items`);if((r.skipped||0)>0)alert((r.conflicts||[]).slice(0,10).map(x=>x.message).join('\n')||'Duplicate rows skipped');loadProducts()}else{state.suppliers=await api('/api/suppliers');const m=modal('Post AI Purchase',`<div class="formgrid"><label>Invoice No<input id="aipi" class="input"></label><label>Supplier<select id="aips" class="select"><option value="">AI Import Supplier</option>${state.suppliers.map(x=>`<option value="${x.Id}">${esc(x.Name)}</option>`).join('')}</select></label><label>Payment Mode<select id="aipm" class="select"><option>Credit</option><option>Cash</option><option>UPI</option><option>Card</option></select></label><label>Paid Amount<input id="aipa" class="input" type="number" value="0"></label><label>Discount<input id="aidisc" class="input" type="number" value="0"></label></div>`,`<button class="btn" onclick="postAIPurchase()">Post Purchase</button>`);window.aiPurModal=m}}catch(e){alert(e.message)}}
async function postAIPurchase(){const sid=Number(aips.value)||null;const sup=state.suppliers.find(x=>x.Id===sid);try{const r=await api('/api/ai/import/purchase/commit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({InvoiceNo:aipi.value||null,SupplierId:sid,SupplierName:sup?.Name||'AI Import',PaymentMode:aipm.value,PaidAmount:+aipa.value,Discount:+aidisc.value,Rows:state.aiRows})});closeModal();toast('AI purchase posted and stock updated');loadPurchase()}catch(e){alert(e.message)}}

async function loadSettings(){setPage('settings');title.textContent='Settings';const [x,o,types]=await Promise.all([api('/api/settings'),api('/api/outlet'),api('/api/outlet-types')]);document.querySelector('#outletPill').textContent=o.OutletName||'Main Outlet';document.body.dataset.storeType=(o.StoreType||'Retail Shop').replace(/[^a-z0-9]+/gi,'-').toLowerCase();app.innerHTML=`<div class="content"><div class="twocol"><div class="panel"><h3>COMPANY & INVOICE</h3><div class="formgrid"><label>Company Name<input id="sn" class="input" value="${esc(x.CompanyName)}"></label><label>Invoice Prefix<input id="si" class="input" value="${esc(x.InvoicePrefix)}"></label><label>Phone<input id="spn" class="input" value="${esc(x.Phone)}"></label><label>GSTIN<input id="sg" class="input" value="${esc(x.Gstin)}"></label><label class="full">Address<textarea id="sa" class="textarea">${esc(x.Address)}</textarea></label></div><button class="btn" style="margin-top:12px" onclick="saveSettings()">Save Settings</button></div><div class="panel"><h3>OUTLET MASTER</h3><p class="muted">Store type changes the terminology and inventory rules used by the UI.</p><div class="formgrid"><label>Outlet Name<input id="oname" class="input" value="${esc(o.OutletName||'Main Outlet')}"></label><label>Store Type<select id="otype" class="select" onchange="applyStoreDefaults()">${types.map(t=>`<option ${t===o.StoreType?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Phone<input id="ophone" class="input" value="${esc(o.Phone||'')}"></label><label>GSTIN<input id="ogst" class="input" value="${esc(o.Gstin||'')}"></label><label class="full">Address<textarea id="oaddr" class="textarea">${esc(o.Address||'')}</textarea></label><label class="full"><input id="oreqbatch" type="checkbox" ${o.RequireBatch?'checked':''}> Batch mandatory &nbsp;&nbsp; <input id="oreqexp" type="checkbox" ${o.RequireExpiry?'checked':''}> Expiry mandatory</label></div><button class="btn" style="margin-top:12px" onclick="saveOutlet()">Save Outlet Master</button></div></div><div class="panel" style="margin-top:14px"><h3>AI CONFIGURATION</h3><p class="muted">AI import supports scanned PDF, Excel, images/handwritten notes and pasted messages. For privacy, the AI service is optional and only used when an API key is configured.</p><div class="formgrid"><label>OpenAI API Key<input id="oaikey" class="input" type="password" placeholder="Leave blank to keep existing key"></label><label>Model<input id="oaimodel" class="input" value="gpt-5.6-luna"></label></div><button class="btn" style="margin-top:12px" onclick="saveAISettings()">Save AI Settings</button></div><div class="panel" style="margin-top:14px"><h3>LOCAL DATABASE</h3><p class="muted">Database: <b>SuvidhaPOS</b> • SQL Server local</p><button class="btn" onclick="backup()">💾 Create Backup Now</button></div></div>`}
async function applyStoreDefaults(){const t=(otype?.value||'').toLowerCase();const pharma=t.includes('pharmacy')||t.includes('medical');const agri=t.includes('agriculture')||t.includes('pesticide')||t.includes('seeds');if(pharma){oreqbatch.checked=true;oreqexp.checked=true}else if(agri){oreqbatch.checked=true;oreqexp.checked=false}}
async function saveOutlet(){try{const r=await api('/api/outlet',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({OutletName:oname.value,StoreType:otype.value,Address:oaddr.value,Phone:ophone.value,Gstin:ogst.value,RequireBatch:oreqbatch.checked,RequireExpiry:oreqexp.checked,DefaultUnit:'PCS'})});toast('Outlet master saved');document.querySelector('#outletPill').textContent=oname.value;if(window.refreshLoginOutlet)window.refreshLoginOutlet(true);window.dispatchEvent(new CustomEvent('suvidha:outlet-changed'));loadSettings();setTimeout(()=>location.reload(),650)}catch(e){alert(e.message)}}
async function saveAISettings(){try{if(oaikey.value)await api('/api/app-settings/OpenAI.ApiKey',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({Value:oaikey.value})});await api('/api/app-settings/OpenAI.Model',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({Value:oaimodel.value})});toast('AI settings saved')}catch(e){alert(e.message)}}

async function saveSettings(){try{await api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({CompanyName:sn.value,Address:sa.value,Phone:spn.value,Gstin:sg.value,InvoicePrefix:si.value})});toast('Settings saved')}catch(e){alert(e.message)}}
async function backup(){try{const x=await api('/api/backup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({Folder:null})});toast('Backup created: '+x.file)}catch(e){alert('Backup failed: '+e.message)}}
async function loadDayClosing(){const x=await api('/api/day-closing');modal('Day Closing',`<div class="metricrow"><div class="mini">Cash Sales<b>₹${money(x.CashSales)}</b></div><div class="mini">Cash In<b>₹${money(x.CashIn)}</b></div><div class="mini">Cash Out<b>₹${money(x.CashOut)}</b></div><div class="mini">Expected Cash<b>₹${money(Number(x.CashSales)+Number(x.CashIn)-Number(x.CashOut))}</b></div></div><div class="formgrid" style="margin-top:15px"><label>Opening Cash<input id="dcOpen" class="input" type="number" value="0"></label><label>Actual Closing Cash<input id="dcClose" class="input" type="number" value="0"></label><label class="full">Notes<input id="dcNotes" class="input"></label></div>`,`<button class="btn" onclick="closeDay()">Close Day</button>`)}
async function closeDay(){const x=await api('/api/day-closing');try{await api('/api/day-closing',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({OpeningCash:+dcOpen.value,CashSales:+x.CashSales,CashIn:+x.CashIn,CashOut:+x.CashOut,ClosingCash:+dcClose.value,Notes:dcNotes.value})});closeModal();toast('Day closed successfully')}catch(e){alert(e.message)}}
async function loadUsers(){const rows=await api('/api/users');modal('User Management',`<div class="toolbar"><button class="btn" onclick="openUser()">＋ Add User</button></div><div class="tablewrap"><table class="table"><thead><tr><th>USERNAME</th><th>NAME</th><th>ROLE</th><th>STATUS</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.UserName)}</td><td>${esc(x.DisplayName)}</td><td>${esc(x.Role)}</td><td>${x.IsActive?'Active':'Disabled'}</td><td><button class="btn small secondary" onclick="toggleUser(${x.Id})">Toggle</button></td></tr>`).join('')}</tbody></table></div>`)}
function openUser(){modal('Add User',`<div class="formgrid"><label>Username<input id="un" class="input"></label><label>Display Name<input id="ud" class="input"></label><label>Password<input id="up" class="input" type="password"></label><label>Role<select id="ur" class="select"><option>Cashier</option><option>Manager</option><option>Admin</option></select></label></div>`,`<button class="btn" onclick="saveUser()">Create User</button>`)}
async function saveUser(){try{await api('/api/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({UserName:un.value,DisplayName:ud.value,Password:up.value,Role:ur.value})});closeModal();loadUsers()}catch(e){alert(e.message)}}
async function toggleUser(id){await api('/api/users/'+id+'/toggle',{method:'POST'});loadUsers()}

function modal(head,body,actions=''){const m=document.createElement('div');m.className='modal open';m.id='modal';m.innerHTML=`<div class="modalbox"><div class="panelhead"><h2>${head}</h2><button class="btn small secondary" onclick="closeModal()">×</button></div>${body}<div class="toolbar" style="justify-content:flex-end;margin-top:15px">${actions}<button class="btn secondary" onclick="closeModal()">Cancel</button></div></div>`;document.body.appendChild(m);return m}
function closeModal(){document.querySelectorAll('.modal').forEach(x=>x.remove())}

const sidebarRoutes={
  dashboard:['loadDashboard'],
  billing:['loadBilling'],
  products:['loadProducts'],
  openingstock:['loadOpeningStockMaster','loadOpeningStock'],
  purchase:['loadPurchase'],
  sales:['loadSales'],
  billmaster:['loadBillMaster'],
  customers:['loadCustomers'],
  suppliers:['loadSuppliers'],
  aiimport:['loadAIImport'],
  itemimport:['loadNormalItemImportMaster','loadAIImport'],
  barcodemaster:['loadBarcodePrintMaster'],
  expiry:['loadExpiry'],
  returns:['loadReturns'],
  expenses:['loadExpenses'],
  taxmaster:['loadTaxMaster','loadTaxmaster'],
  unitmaster:['loadUnitMaster','loadUnitmaster'],
  reports:['loadReports']
};
function resolveSidebarRoute(page){
  const names=sidebarRoutes[page]||sidebarRoutes.dashboard;
  for(const name of names){
    const fn=window[name];
    if(typeof fn==='function')return fn;
  }
  return typeof window.loadDashboard==='function'?window.loadDashboard:null;
}
function navigateFromSidebar(page){
  const fn=resolveSidebarRoute(page);
  if(!fn){
    app.innerHTML=errorBox(new Error('Page module is not loaded: '+page));
    return;
  }
  try{
    const p=fn();
    if(p&&typeof p.catch==='function')p.catch(e=>{app.innerHTML=errorBox(e)});
  }catch(e){
    app.innerHTML=errorBox(e);
  }
}
window.resolveSidebarRoute=resolveSidebarRoute;
window.navigateFromSidebar=navigateFromSidebar;
const sidebar=document.querySelector('#sidebar');
if(sidebar){
  sidebar.addEventListener('click',e=>{
    const b=e.target.closest&&e.target.closest('.nav[data-page]');
    if(!b||!sidebar.contains(b))return;
    if(document.body.classList.contains('jewel-suite-mode')&&b.classList.contains('js-nav')&&b.getAttribute('onclick'))return;
    e.preventDefault();
    navigateFromSidebar(b.dataset.page);
  });
}
async function boot(){
  let token=null;try{token=sessionStorage.getItem('suvidha_auth_token')}catch{}
  if(!token){
    const screen=document.querySelector('#loginScreen');
    if(screen)screen.style.display='flex';
    return;
  }
  window.suvidhaAuthToken=token;
  try{
    const raw=await api('/api/me');
    currentUser={
      Id:raw.Id??raw.id,
      UserName:raw.UserName??raw.userName??'',
      DisplayName:raw.DisplayName??raw.displayName??raw.UserName??raw.userName??'User',
      Role:raw.Role??raw.role??'User'
    };
    window.currentUser=currentUser;
    const screen=document.querySelector('#loginScreen');
    if(screen)screen.style.setProperty('display','none','important');
    document.querySelector('#userPill').textContent=currentUser.DisplayName+' · '+currentUser.Role;
    if(typeof window.refreshLicenseStatus==='function')await window.refreshLicenseStatus(true);
    loadDashboard();
  }catch(e){
    try{sessionStorage.removeItem('suvidha_auth_token')}catch{}
    window.suvidhaAuthToken=null;
    const screen=document.querySelector('#loginScreen');
    if(screen)screen.style.display='flex';
  }
}
boot();loadHealth();

document.addEventListener('keydown',e=>{if(document.querySelector('#loginScreen')?.style.display!=='none' && e.key==='Enter')login(); if(e.ctrlKey&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#billSearch')?.focus();}});
